run(){ desc="$1"; shift; printf '%s' "$1" > /tmp/k1.bin; /workspace/dataset/test19_executable --k1="$1" --v1 1 --k2 K2 --v2 2 >/tmp/o.txt 2>/tmp/e.txt; rc=$?;
 echo "### $desc  argv-bytes: $(od -An -tx1 /tmp/k1.bin | tr -s ' ')  RC=$rc";
 echo "--stdout--"; od -An -c /tmp/o.txt; echo "--stderr--"; od -An -c /tmp/e.txt; echo; }
